/* Q(): show a string literally even though the renderer turns entities back into characters (&amp;lt; is shown as &lt;) */
const Q=s=>String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
const ord=a=>a.join(", ");
const alts=a=>{const out=[];for(let i=0;i<a.length-1;i++){const b=a.slice();[b[i],b[i+1]]=[b[i+1],b[i]];out.push(ord(b))}out.push(ord(a.slice().reverse()));return out};
const sv=s=>s.split(".").map(Number);
const vcmp=(a,b)=>{for(let i=0;i<3;i++)if(a[i]!==b[i])return a[i]-b[i];return 0};
const inRange=(range,ver)=>{const v=sv(ver);if(range[0]==="^"||range[0]==="~"){const b=sv(range.slice(1));const up=range[0]==="~"?[b[0],b[1]+1,0]:b[0]>0?[b[0]+1,0,0]:b[1]>0?[0,b[1]+1,0]:[0,0,b[2]+1];return vcmp(v,b)>=0&&vcmp(v,up)<0}if(range.slice(0,2)===">=")return vcmp(v,sv(range.slice(2)))>=0;return vcmp(v,sv(range))===0};
const Lb=n=>String.fromCharCode(65+n);
const byteLen=s=>[...s].reduce((n,ch)=>{const c=ch.codePointAt(0);return n+(c<0x80?1:c<0x800?2:c<0x10000?3:4)},0);

