  ()=>T([["docker build -t app .","builds an image from the Dockerfile in the current folder and tags it app"],["docker run -p 8080:3000 app","starts a container from the image and maps host port 8080 to container port 3000"],["docker ps","lists running containers"],["docker images","lists images stored on this machine"],["docker stop web","stops the container named web"],["docker exec -it web sh","opens a shell inside the running container"],["docker compose up","starts all services described in compose.yaml"]],k=>`What does ${k} do?`,v=>`Which command ${v}?`,r=>`${r[0]} ${r[1]}.`),
  ()=>{const h=pick([8080,8000,5000,4000]),c=pick([3000,80,5173,8000]);return M(`You run docker run -p ${h}:${c} web. Which URL do you open in the browser on your computer?`,`http://localhost:${h}`,[`http://localhost:${c}`,`http://localhost:${h}:${c}`,`http://web:${h}`,`http://localhost:${h+1}`,`http://localhost`].filter(x=>x!==`http://localhost:${h}`),`-p host:container maps a port on your machine (${h}) to a port inside the container (${c}). You always use the host port from outside.`)},
  ()=>{const n=rnd(5,9),k=rnd(2,n-1);return nat(`A Dockerfile creates ${n} layers. Docker caches layers, so if the file changes at layer ${k}, layers ${k} to ${n} are rebuilt and layers before ${k} come from the cache. How many layers are rebuilt?`,n-k+1,`Layers ${k} through ${n} are rebuilt: ${n} − ${k} + 1 = ${n-k+1}. That is why rarely-changing steps (installing dependencies) come before frequently-changing ones (copying source).`)},
  ()=>either(.5,()=>M(`Which Dockerfile order gives the best cache use for a Node app?`,`COPY package*.json ./ then RUN npm ci then COPY . .`,[`COPY . . then RUN npm ci`,`RUN npm ci then COPY package*.json ./`,`COPY . . then COPY package*.json ./`],`Dependencies change less often than source code. Copy the package files, install, and only then copy the source, so a source edit does not reinstall everything.`),
    ()=>{const base=rnd(80,200),a=rnd(10,60),b=rnd(10,60),c=rnd(10,60);return nat(`Three images all use the same ${base} MB base layers, and add ${a} MB, ${b} MB and ${c} MB of their own layers. Docker stores shared layers once. How many MB of disk do the three images use in total?`,base+a+b+c,`The base is stored once: ${base} + ${a} + ${b} + ${c} = ${base+a+b+c} MB. Without sharing it would be ${3*base+a+b+c} MB.`)}),
  ()=>either(.5,()=>M(`How does a container differ from a virtual machine?`,`A container shares the host’s kernel and starts in seconds; a VM runs a full guest operating system`,[`A container needs a hypervisor and a full OS`,`They are exactly the same`,`A VM shares the host kernel`],`Containers are isolated processes using the host kernel, so they are lighter and start faster than VMs.`),
    ()=>M(`A container writes user uploads to its own filesystem. The container is removed and recreated. What happens to the uploads?`,`They are lost unless a volume or bind mount stores them outside the container`,[`They are kept automatically`,`They move to the image`,`They are copied to every container`],`A container’s writable layer disappears with the container. Use volumes for data that must survive.`)),
  ()=>either(.5,()=>M(`Why use a multi-stage Dockerfile for a React app?`,`Build with Node in one stage, then copy only the built files into a small web-server image`,[`To run the app twice`,`To make Node available to users`,`To hide the Dockerfile`],`The final image holds only what runs in production (for example nginx and the dist folder), not compilers and dev dependencies, so it is smaller and has fewer vulnerabilities.`),
    ()=>M(`What should a .dockerignore file usually contain?`,`node_modules, .git and local .env files`,[`The Dockerfile itself`,`package.json`,`The source code`],`Ignoring these keeps the build context small and stops secrets and huge folders being copied into the image.`)),
  ()=>T([["Image","a read-only template made of layers that contains the app and its dependencies"],["Container","a running instance of an image"],["Dockerfile","a text file of instructions for building an image"],["Registry","a server that stores and distributes images, such as Docker Hub"],["Volume","storage that lives outside a container and can outlast it"],["Compose","a tool for defining and running several containers together"]],k=>`What is ${k==="Compose"?"Docker Compose":"a Docker "+k.toLowerCase()}?`.replace("a Docker image","a Docker image"),v=>`Which Docker term means: ${v}?`,r=>`${r[0]}: ${r[1]}.`)
